export const dictionaries = { "pt-BR": pt, en, es };

function getPath(object, path) {
  return path.split(".").reduce((value, key) => value?.[key], object);
}

export function translate(locale, path, values = {}) {
  const dictionary = dictionaries[locale] || dictionaries["pt-BR"];
  const raw = getPath(dictionary, path) ?? getPath(dictionaries["pt-BR"], path) ?? path;
  if (typeof raw !== "string") return raw;
  return Object.entries(values).reduce((text, [key, value]) => text.replaceAll(`{${key}}`, String(value)), raw);
}

export function issueCopy(locale, code) {
  return dictionaries[locale]?.issues?.[code] || dictionaries["pt-BR"].issues[code] || {
    title: code,
    found: "",
    why: "",
    impact: "",
    owner: "",
    fix: "",
    reason: "",
  };
}
